    def __init__(self, dim, LayerNorm_type):
        super(LayerNorm, self).__init__()
        if LayerNorm_type == 'BiasFree':
            self.body = nn.LayerNorm(dim, elementwise_affine=False)
        else:
            self.body = nn.LayerNorm(dim)

    def forward(self, x):
